import bpy
from mathutils import Vector
elev=bpy.data.collections.get('01 WORLD | ELEVADOR LACERDA | blockout v4')
if not elev: raise RuntimeError('elevador ausente')
terms=('piso','parede','janela','porta','cobertura','marquise','hall','fachada','bloco')
for o in elev.objects:
    if any(t in o.name.lower() for t in terms):
        if o.type=='MESH':
            pts=[o.matrix_world@Vector(c) for c in o.bound_box]
            print(o.name,'Z',(round(min(p.z for p in pts),3),round(max(p.z for p in pts),3)),'DIMS',tuple(round(v,3) for v in o.dimensions),'LOC',tuple(round(v,3) for v in o.location))
        else: print(o.name,o.type)
print('UPPER_LEVEL_INSPECT_OK')
